using System.Collections.Generic;

public record ProcResult(string Key, int Payload, long ProcessedAt);

public class Processor
{
    private readonly long _window;
    private readonly Dictionary<string, (ProcResult Result, long RecordedAt)> _seen = new();
    public List<(string Key, int Payload)> Effects { get; } = new();

    public Processor(long window)
    {
        _window = window;
    }

    public ProcResult Process(string key, int payload, long now)
    {
        if (_seen.TryGetValue(key, out var cached) && now - cached.RecordedAt < _window)
        {
            return cached.Result;
        }
        Effects.Add((key, payload));
        var result = new ProcResult(key, payload, now);
        _seen[key] = (result, now);
        return result;
    }
}

