using Xunit;

public class ProcessorTests
{
    [Fact]
    public void DuplicateKeyWithinWindowNotReexecuted()
    {
        var p = new Processor(10);
        var first = p.Process("order-1", 5, 0);
        var second = p.Process("order-1", 999, 5);
        Assert.Equal(first, second);
        Assert.Single(p.Effects);
    }

    [Fact]
    public void DifferentKeysBothExecute()
    {
        var p = new Processor(10);
        p.Process("a", 1, 0);
        p.Process("b", 2, 0);
        Assert.Equal(2, p.Effects.Count);
    }

    [Fact]
    public void ReexecutesAfterWindowExpires()
    {
        var p = new Processor(10);
        p.Process("order-1", 5, 0);
        p.Process("order-1", 5, 9);
        Assert.Single(p.Effects);
        p.Process("order-1", 7, 10);
        Assert.Equal(2, p.Effects.Count);
        Assert.Equal(7, p.Effects[1].Payload);
    }
}
